import tokensJson from './tokens.json';

/**
 * Colour tokens generated by `brand/tools/generate_brand.py`. The JSON file is
 * the single source of truth so the app and the brand exports cannot drift.
 */
export interface ColourTokenFile {
  brand: Record<string, string>;
  themes: { light: Record<string, string>; dark: Record<string, string> };
  contrast: ContrastCheck[];
}

/** One measured foreground/background pair, verified at build time. */
export interface ContrastCheck {
  theme: string;
  foreground: string;
  background: string;
  ratio: number;
  target: number;
  level: string;
  passes: boolean;
}

export const tokens = tokensJson as unknown as ColourTokenFile;
